"""Episode 3 source screenplay as data. All speech invented unless tag explicitly says otherwise.
Build script and six Ep2-schema plans with _build.py --write. No external packages or network.
"""
SEGS = ('coldopen', 'act1', 'act2', 'act3', 'act4', 'tag')
ACT = dict(zip(SEGS, ('COLD OPEN', 'ACT ONE', 'ACT TWO', 'ACT THREE', 'ACT FOUR', 'TAG')))
ACT_TITLE = dict(zip(SEGS, ('one fruit', 'the preview', 'people out, money in', 'keep building', 'twelve days', 'say a number')))
SCENES = {}
NEW = {s: [] for s in SEGS}
NEW_LINES = {}
NEW_VO = {}
ROOMS = {}
CAST = {
 'mas': ('MAS', 'CEO'), 'gerg': ('GERG', 'CO-FOUNDER'), 'rima': ('RIMA', 'CTO'),
 'mario': ('MARIO', 'RIVAL'), 'adelina': ('ADELINA', 'TURNS ESSAYS INTO REVENUE'),
 'nole': ('NOLE', 'RIVAL'), 'auhsoj': ('AUHSOJ', 'LEADS THE ROUND'),
 'maon': ('MAON', 'MODEL LEAD'), 'lunchmas': ('LUNCHMAS', 'CO-FOUNDER'),
 'corkboard-guy': ('CORKBOARD GUY', 'HAS A THEORY'), 'second-truther': ('SECOND TRUTHER', 'WANTS LUNCH'),
 'cook': ('COOK', 'TACO TRUCK'), 'installer': ('INSTALLER', 'DOORS'),
 'lifeguard': ('LIFEGUARD', 'BEACH'), 'investor': ('INVESTOR', 'THE MONEY'),
 'customer': ('CUSTOMER', 'CUSTOMER'), 'moswen': ('MOSWEN', 'GOVERNOR'),
 'reneiw': ('RENEIW', 'SENATOR'), 'announcer': ('ANNOUNCER', 'STADIUM PA'),
 'chatgtp': ('CHATGTP', 'CHATBOT'), 'sucram': ('SUCRAM', 'CRITIC'),
 'mit-kooc': ('MIT KOOC', 'ELPPA'), 'rumpt': ('RUMPT', 'PRESIDENT-ELECT'),
 'staffer': ('STAFFER', 'THE BUILD'), 'orb': ('THE ORB', 'WITNESS'),
 'o1': ('o1', 'PREVIEW'), 'alyi': ('ALYI', 'CO-FOUNDER'),
}
_current = None
_counts = {}
_lcounts = {}
_vcount = 0

def scene(id, seg, title, date, place, set, room, music, seam, *, mode='CONVERSATION', pace='normal'):
 global _current
 _current = str(id)
 SCENES[_current] = dict(seg=seg, title=title, date=date, place=place, set=set, room=room,
                        music=music, seam=seam, mode=mode, pace=pace, status='CHANGED')
 ROOMS[room] = 'continuous location bed; lead next room by 0.6 s on sound-led seam'

def b(visual, picture, chars=(), lines=(), *, frame='TWO SHOT; hold through the exchange, cut on its turn', dur=None,
      air=1.6, head=None, text=(), vo=None, delivery='conversational; complete thoughts; no imitation',
      sounds=(), style='BASE', flashback=None, tag='[INVENTED]', text_mode='sequential'):
 global _vcount
 sc = SCENES[_current]; seg = sc['seg']
 _counts[_current] = _counts.get(_current, 0) + 1
 bid = f'{_current}.{_counts[_current]:02d}'
 first = _counts[_current] == 1
 h = (2.0 if first else 0.5) if head is None else head
 ls = []
 if vo is not None:
  _vcount += 1
  lid = f'e3-vo-{_vcount:02d}'
  ln = dict(id=lid, who='mas', text=vo, vo=True, delivery='close dry thought, lowercase, unhurried, never a slogan', tag='[INVENTED · inner voice]', gap_s=0.5)
  ls.append(ln); NEW_VO[lid] = (seg, bid, ln)
 for who, words in lines:
  _lcounts[seg] = _lcounts.get(seg, 0) + 1
  lid = f'e3-{seg}-{_lcounts[seg]:04d}'
  ln = dict(id=lid, who=who, text=words, delivery=delivery, tag=tag,
            gap_s=0.45 if who == 'mas' else 0.3 if sc['pace']=='quick' else 0.5)
  ls.append(ln); NEW_LINES[lid] = dict(ln, seg=seg, beat=bid)
 figures = list(dict.fromkeys(list(chars)+[l['who'] for l in ls]))
 NEW[seg].append(dict(id=bid, scene=_current, visual=visual, caption=picture,
   picture=f'VISUAL: {visual}. {picture}', camera=frame, frame=frame, chars=figures,
   set=sc['set'], room=sc['room'], set_id='SET-'+sc['set'].upper(), mode=sc['mode'], pace=sc['pace'],
   lines=ls, head=h, air=air, dur=dur, text=list(text), music=sc['music'], sounds=list(sounds),
   style=style, flashback=flashback, first=first,text_mode=text_mode))

